import React, { useRef, useState } from 'react';
import { CameraIcon, UploadIcon, PhotoIcon } from './icons';
import { motion } from 'framer-motion';

interface ImageUploaderProps {
  onImageSelected: (file: File) => void;
  onTakePhoto: () => void;
}

const ImageUploader: React.FC<ImageUploaderProps> = ({ onImageSelected, onTakePhoto }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [isDragging, setIsDragging] = useState(false);

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    if (event.target.files && event.target.files[0]) {
      onImageSelected(event.target.files[0]);
    }
  };

  const handleClick = () => {
    fileInputRef.current?.click();
  };

  const handleDragEnter = (e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragging(true);
  };

  const handleDragLeave = (e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragging(false);
  };

  const handleDragOver = (e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.stopPropagation();
  };

  const handleDrop = (e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragging(false);
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      onImageSelected(e.dataTransfer.files[0]);
    }
  };

  return (
    <div className="w-full max-w-2xl flex flex-col items-center">
      <motion.div 
        initial={{ y: 20, opacity: 0 }}
        animate={{ y: 0, opacity: 1 }}
        transition={{ duration: 0.5 }}
        className="text-center mb-8"
      >
        <h2 className="text-3xl md:text-4xl font-bold text-white mb-2 tracking-tight">
            O que vamos comer hoje?
        </h2>
        <p className="text-gray-400 text-lg">
            Envie uma <span className="text-emerald-400 font-medium">foto real</span> do seu alimento ou produto.
        </p>
      </motion.div>

      <input
        type="file"
        ref={fileInputRef}
        onChange={handleFileChange}
        className="hidden"
        accept="image/*"
        /* capture="environment" removido para permitir abrir a galeria */
      />

      <motion.div 
        whileHover={{ scale: 1.01 }}
        whileTap={{ scale: 0.99 }}
        onDragEnter={handleDragEnter}
        onDragLeave={handleDragLeave}
        onDragOver={handleDragOver}
        onDrop={handleDrop}
        onClick={handleClick}
        className={`w-full relative cursor-pointer group overflow-hidden rounded-3xl border-2 border-dashed transition-all duration-300 p-10 md:p-16 flex flex-col items-center justify-center
          ${isDragging 
            ? 'border-emerald-500 bg-emerald-900/20 shadow-[0_0_30px_rgba(16,185,129,0.2)]' 
            : 'border-gray-700 bg-gray-800/40 hover:bg-gray-800/60 hover:border-emerald-500/50 hover:shadow-2xl'}`}
      >
        {/* Background subtle glow */}
        <div className="absolute inset-0 bg-gradient-to-br from-emerald-500/5 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-500"></div>

        <motion.div 
            animate={isDragging ? { scale: 1.1, rotate: 5 } : { scale: 1, rotate: 0 }}
            className="mb-6 relative z-10"
        >
             <div className="p-5 rounded-full bg-gray-800 border border-gray-700 shadow-xl group-hover:border-emerald-500/30 group-hover:shadow-emerald-500/20 transition-all duration-300">
                <UploadIcon className={`w-12 h-12 ${isDragging ? 'text-emerald-400' : 'text-gray-400 group-hover:text-emerald-400'} transition-colors`} />
             </div>
        </motion.div>

        <h3 className="text-xl font-semibold text-gray-200 mb-2 relative z-10">
          Toque para enviar ou arraste
        </h3>
        <p className="text-gray-500 text-sm relative z-10 font-medium text-center px-4">
           Aceitamos refeições, ingredientes ou embalagens (caixas, latas, etc.)
        </p>
      </motion.div>

      <div className="flex flex-col sm:flex-row items-center justify-center gap-4 w-full mt-8">
            <motion.button
                whileHover={{ scale: 1.05, backgroundColor: "rgba(16, 185, 129, 1)" }}
                whileTap={{ scale: 0.95 }}
                onClick={handleClick}
                className="flex-1 w-full sm:w-auto bg-gray-800 border border-gray-700 hover:border-emerald-500 text-gray-200 font-semibold py-4 px-6 rounded-xl transition-all shadow-lg hover:shadow-emerald-500/10 inline-flex items-center justify-center gap-3"
            >
                <PhotoIcon className="w-6 h-6 text-emerald-400" />
                Galeria
            </motion.button>

            <motion.button
                whileHover={{ scale: 1.05 }}
                whileTap={{ scale: 0.95 }}
                onClick={onTakePhoto}
                className="flex-1 w-full sm:w-auto bg-gradient-to-r from-emerald-600 to-emerald-500 text-white font-bold py-4 px-6 rounded-xl hover:shadow-lg hover:shadow-emerald-500/30 transition-all inline-flex items-center justify-center gap-3"
            >
                <CameraIcon className="w-6 h-6" />
                Tirar Foto
            </motion.button>
      </div>
    </div>
  );
};

export default ImageUploader;

import { GoogleGenAI, Type } from '@google/genai';
import type { AnalysisResult } from '../types';

const API_KEY = process.env.API_KEY;

if (!API_KEY) {
  throw new Error("API_KEY environment variable not set");
}

const ai = new GoogleGenAI({ apiKey: API_KEY });

const responseSchema = {
  type: Type.OBJECT,
  properties: {
    isRealFood: {
      type: Type.BOOLEAN,
      description: 'Defina como true se a imagem for uma fotografia real de comida, refeição ou PRODUTO ALIMENTÍCIO (embalagens, caixas, latas, garrafas). Defina como false para desenhos, telas de computador, pessoas ou objetos não comestíveis.'
    },
    totalCalories: {
      type: Type.INTEGER,
      description: 'O total de calorias. Se isRealFood for false, deve ser 0.'
    },
    foods: {
      type: Type.ARRAY,
      description: 'Lista de alimentos identificados. Se isRealFood for false, envie uma lista vazia.',
      items: {
        type: Type.OBJECT,
        properties: {
          name: {
            type: Type.STRING,
            description: 'O nome específico do alimento ou produto (ex: Leite Integral, Biscoito Recheado).'
          },
          calories: {
            type: Type.INTEGER,
            description: 'A contagem de calorias estimada.'
          },
          quantity: {
            type: Type.STRING,
            description: 'A quantidade estimada (ex: 100g, 1 caixa, 1 copo, 200ml).'
          },
          carbohydrates: {
            type: Type.NUMBER,
            description: 'Carboidratos em gramas.'
          },
          protein: {
            type: Type.NUMBER,
            description: 'Proteína em gramas.'
          },
          fat: {
            type: Type.NUMBER,
            description: 'Gordura em gramas.'
          }
        },
        required: ['name', 'calories', 'quantity', 'carbohydrates', 'protein', 'fat']
      }
    },
    feedback: {
        type: Type.STRING,
        description: 'Se isRealFood for false, explique polidamente que o app só analisa fotos reais de alimentos ou produtos alimentícios. Se for true, dê o feedback nutricional.'
    },
    suggestions: {
        type: Type.ARRAY,
        description: 'Sugestões práticas de saúde ou consumo. Se isRealFood for false, envie uma lista vazia.',
        items: {
            type: Type.OBJECT,
            properties: {
                title: { type: Type.STRING },
                details: { type: Type.STRING }
            },
            required: ['title', 'details']
        }
    }
  },
  required: ['isRealFood', 'totalCalories', 'foods', 'feedback', 'suggestions']
};

export const analyzeImage = async (base64Image: string): Promise<AnalysisResult> => {
  const imagePart = {
    inlineData: {
      mimeType: 'image/jpeg',
      data: base64Image
    }
  };

  const textPart = {
    text: `Você é um nutricionista rigoroso e um especialista em visão computacional.

    SUA PRIMEIRA E MAIS IMPORTANTE TAREFA É A VALIDAÇÃO DA IMAGEM.

    CRITÉRIOS DE REJEIÇÃO (isRealFood = false):
    1. Desenhos, ilustrações, cartoons, animes ou arte digital.
    2. Imagens de telas (fotos de monitores, TVs ou celulares exibindo comida).
    3. Objetos que NÃO são comida nem produtos alimentícios (carros, pessoas, paisagens, eletrônicos, móveis, animais vivos).
    4. Imagens excessivamente borradas onde nada é distinguível.

    CRITÉRIOS DE ACEITE (isRealFood = true):
    1. Fotografias reais de refeições prontas (pratos, lanches).
    2. Fotografias reais de PRODUTOS ALIMENTÍCIOS e EMBALAGENS (ex: caixas de leite, latas de achocolatado (Nescau, Toddy), pacotes de biscoito, sacos de salgadinho, garrafas de suco/refrigerante).
    3. Fotografias reais de ingredientes crus (frutas, legumes, carnes, ovos).

    Se a imagem for rejeitada:
    - Defina 'isRealFood' como false.
    - Defina 'totalCalories' como 0.
    - Deixe a lista 'foods' vazia.
    - No 'feedback', explique que o Flavos Healthy analisa apenas alimentos reais ou produtos alimentícios (inclusive embalagens).

    Se a imagem for aceita (Comida ou Produto):
    - Identifique o alimento. Se for um produto embalado, leia o rótulo ou identifique a marca/tipo visualmente.
    - Estime as calorias:
      * Se for uma refeição: baseie-se nos ingredientes visíveis.
      * Se for um produto (ex: caixa de Nescau): Estime com base em uma porção padrão (ex: 2 colheres de sopa ou 200ml preparado) ou na embalagem inteira se for um snack individual. Especifique na 'quantity' qual foi a base (ex: "Porção de 20g").
    - Analise com precisão técnica.
    - Sugira harmonizações ou alternativas saudáveis nas 'suggestions'.

    Responda estritamente no formato JSON solicitado.`
  };

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: { parts: [imagePart, textPart] },
      config: {
        responseMimeType: "application/json",
        responseSchema: responseSchema,
      }
    });

    const jsonText = response.text.trim();
    const result = JSON.parse(jsonText) as AnalysisResult;
    return result;

  } catch (error) {
    console.error("Error calling Gemini API:", error);
    throw new Error("Falha ao processar a imagem. Tente novamente.");
  }
};

